import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';

/**
 * In dev, the fake API runs in a Service Worker (public/mockServiceWorker.js,
 * generated by `npx msw init public`). The app waits for it before rendering,
 * otherwise the very first requests would go out before it is listening.
 */
async function enableMocking() {
  if (!import.meta.env.DEV) return;
  const { worker } = await import('./mocks/browser');
  // Vite's own requests (modules, HMR, assets) are not ours: let them through.
  await worker.start({ onUnhandledFrame: 'bypass' });
}

void enableMocking().then(() => {
  createRoot(document.getElementById('root')!).render(
    <StrictMode>
      <App />
    </StrictMode>,
  );
});
